// ================================================================
//  📍 INSTANT READING PROGRESS CHECKPOINT HELPERS (PER-CATEGORY PERSISTENT)
// ================================================================
window.caReadingCheckpointsCache = null;

function _getCaReadingStorageKey() {
  return `ca_reading_checkpoint_${(window.caConfig && window.caConfig.month) || 'module'}`;
}

window.getAllReadingCheckpoints = function() {
  if (window.caReadingCheckpointsCache && typeof window.caReadingCheckpointsCache === 'object') {
    return window.caReadingCheckpointsCache;
  }
  const key = _getCaReadingStorageKey();
  let data = null;
  try {
    const raw = localStorage.getItem(key);
    if (raw) data = JSON.parse(raw);
  } catch(e) {}
  if (!data) {
    try {
      const rawSession = sessionStorage.getItem(key);
      if (rawSession) data = JSON.parse(rawSession);
    } catch(e) {}
  }
  window.caReadingCheckpointsCache = (data && typeof data === 'object') ? data : {};
  return window.caReadingCheckpointsCache;
};

window.getReadingCheckpoint = function(catId) {
  try {
    const data = window.getAllReadingCheckpoints();
    return data[catId || 'all'] || null;
  } catch(e) { return null; }
};

window.setReadingCheckpoint = function(catId, item) {
  try {
    const key = _getCaReadingStorageKey();
    const data = Object.assign({}, window.getAllReadingCheckpoints());
    const categoryKey = catId || 'all';
    data[categoryKey] = {
      id: item.id,
      bookQNum: item.bookQNum || null,
      question: item.question,
      category: item.category,
      timestamp: Date.now()
    };
    window.caReadingCheckpointsCache = data;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
    try { sessionStorage.setItem(key, JSON.stringify(data)); } catch(e) {}

    // ⚡ Real-time Event Dispatch
    window.dispatchEvent(new CustomEvent('ca_reading_checkpoint_updated', {
      detail: { category: categoryKey, checkpoint: data[categoryKey], allCheckpoints: data }
    }));

    // ⚡ GyanLayer Parent App Bridge Sync
    if (window.dispatchReadingCheckpointEvent) {
      window.dispatchReadingCheckpointEvent(categoryKey, item, false, data);
    }
  } catch(e) {
    console.warn("Error setting reading checkpoint:", e);
  }
};

window.clearReadingCheckpoint = function(catId) {
  try {
    const key = _getCaReadingStorageKey();
    const data = Object.assign({}, window.getAllReadingCheckpoints());
    const categoryKey = catId || 'all';
    delete data[categoryKey];
    window.caReadingCheckpointsCache = data;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
    try { sessionStorage.setItem(key, JSON.stringify(data)); } catch(e) {}

    window.dispatchEvent(new CustomEvent('ca_reading_checkpoint_updated', {
      detail: { category: categoryKey, checkpoint: null, allCheckpoints: data }
    }));

    if (window.dispatchReadingCheckpointEvent) {
      window.dispatchReadingCheckpointEvent(categoryKey, null, true, data);
    }
  } catch(e) {
    console.warn("Error clearing reading checkpoint:", e);
  }
};

window.restoreReadingCheckpoints = function(remoteData) {
  try {
    if (!remoteData || typeof remoteData !== 'object') return;
    const key = _getCaReadingStorageKey();
    const local = window.getAllReadingCheckpoints();
    const merged = Object.assign({}, local, remoteData);
    window.caReadingCheckpointsCache = merged;
    try { localStorage.setItem(key, JSON.stringify(merged)); } catch(e) {}
    try { sessionStorage.setItem(key, JSON.stringify(merged)); } catch(e) {}

    window.dispatchEvent(new CustomEvent('ca_reading_checkpoint_updated', {
      detail: { allCheckpoints: merged }
    }));
  } catch(e) {
    console.warn("Error restoring reading checkpoints:", e);
  }
};

